// Port vanilla JS de React Bits <TiltedCard /> (sans la librairie "motion")
// Les ressorts (useSpring) sont recréés avec une petite boucle requestAnimationFrame.

class Spring {
  constructor(value = 0, { stiffness = 100, damping = 30, mass = 2 } = {}) {
    this.value = value;
    this.target = value;
    this.velocity = 0;
    this.stiffness = stiffness;
    this.damping = damping;
    this.mass = mass;
  }
  set(target) {
    this.target = target;
  }
  step(dt) {
    const force =
      this.stiffness * (this.target - this.value) -
      this.damping * this.velocity;
    this.velocity += (force / this.mass) * dt;
    this.value += this.velocity * dt;
  }
  get settled() {
    return (
      Math.abs(this.target - this.value) < 0.001 &&
      Math.abs(this.velocity) < 0.001
    );
  }
}

export default class TiltedCard {
  constructor(element) {
    this.el = element;

    const d = element.dataset;
    this.rotateAmplitude = d.rotateAmplitude
      ? parseFloat(d.rotateAmplitude)
      : 14;
    this.scaleOnHover = d.scaleOnHover ? parseFloat(d.scaleOnHover) : 1.1;
    this.showTooltip = d.showTooltip !== 'false';
    this.caption = d.caption || element.querySelector('img')?.alt || '';

    // Pas d'effet au toucher ni si l'utilisateur réduit les animations
    this.disabled =
      window.matchMedia('(hover: none)').matches ||
      window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    this.build();
    if (this.disabled) return;

    const main = { stiffness: 100, damping: 30, mass: 2 };
    this.rotateX = new Spring(0, main);
    this.rotateY = new Spring(0, main);
    this.scale = new Spring(1, main);
    this.opacity = new Spring(0, { stiffness: 100, damping: 30, mass: 1 });
    this.rotateCaption = new Spring(0, {
      stiffness: 350,
      damping: 30,
      mass: 1,
    });
    this.captionX = 0;
    this.captionY = 0;
    this.lastY = 0;
    this.raf = 0;
    this.last = 0;

    this.onMove = this.onMove.bind(this);
    this.onEnter = this.onEnter.bind(this);
    this.onLeave = this.onLeave.bind(this);
    this.tick = this.tick.bind(this);

    element.addEventListener('mousemove', this.onMove);
    element.addEventListener('mouseenter', this.onEnter);
    element.addEventListener('mouseleave', this.onLeave);
  }

  build() {
    // Range tout le contenu existant (img, overlay) dans .tilted-card-inner
    this.inner = document.createElement('div');
    this.inner.className = 'tilted-card-inner';
    while (this.el.firstChild) this.inner.appendChild(this.el.firstChild);
    this.el.appendChild(this.inner);

    if (this.showTooltip && this.caption) {
      this.captionEl = document.createElement('figcaption');
      this.captionEl.className = 'tilted-card-caption';
      this.captionEl.textContent = this.caption;
      this.el.appendChild(this.captionEl);
    }
  }

  onMove(e) {
    const rect = this.el.getBoundingClientRect();
    const offsetX = e.clientX - rect.left - rect.width / 2;
    const offsetY = e.clientY - rect.top - rect.height / 2;

    this.rotateX.set((offsetY / (rect.height / 2)) * -this.rotateAmplitude);
    this.rotateY.set((offsetX / (rect.width / 2)) * this.rotateAmplitude);

    this.captionX = e.clientX - rect.left;
    this.captionY = e.clientY - rect.top;

    const velocityY = offsetY - this.lastY;
    this.rotateCaption.set(-velocityY * 0.6);
    this.lastY = offsetY;

    this.start();
  }

  onEnter() {
    this.scale.set(this.scaleOnHover);
    this.opacity.set(1);
    this.start();
  }

  onLeave() {
    this.opacity.set(0);
    this.scale.set(1);
    this.rotateX.set(0);
    this.rotateY.set(0);
    this.rotateCaption.set(0);
    this.start();
  }

  start() {
    if (this.raf) return;
    this.last = performance.now();
    this.raf = requestAnimationFrame(this.tick);
  }

  tick(now) {
    const dt = Math.min((now - this.last) / 1000, 0.05);
    this.last = now;

    const springs = [
      this.rotateX,
      this.rotateY,
      this.scale,
      this.opacity,
      this.rotateCaption,
    ];
    springs.forEach((s) => s.step(dt));

    this.inner.style.transform = `rotateX(${this.rotateX.value}deg) rotateY(${this.rotateY.value}deg) scale(${this.scale.value})`;

    if (this.captionEl) {
      this.captionEl.style.transform = `translate(${this.captionX}px, ${this.captionY}px) rotate(${this.rotateCaption.value}deg)`;
      this.captionEl.style.opacity = Math.max(
        0,
        Math.min(1, this.opacity.value),
      );
    }

    if (springs.every((s) => s.settled)) {
      this.raf = 0;
      return;
    }
    this.raf = requestAnimationFrame(this.tick);
  }

  destroy() {
    if (this.disabled) return;
    cancelAnimationFrame(this.raf);
    this.el.removeEventListener('mousemove', this.onMove);
    this.el.removeEventListener('mouseenter', this.onEnter);
    this.el.removeEventListener('mouseleave', this.onLeave);
  }
}
